typedef ptrdiff_t iz;
typedef size_t    uz;
typedef int32_t   b32;
#endif

#if defined(affirm)
   // the includer's, e.g. to report the line
#elif defined(ARIEL_TRAP) || defined(ARIEL_TEST)
#  define affirm(c)  while (!(c)) __builtin_trap()
#else
#  define affirm(c)  while (!(c)) __builtin_unreachable()
#endif
#define countof(a)   (iz)(sizeof(a) / sizeof(*(a)))
#define S(s)         (ariel_Str){(u8 *)s, countof(s)-1}

static void xcpy(void *d, void *s, iz n) { if (n) __builtin_memcpy(d, s, (uz)n); }
static void xmov(void *d, void *s, iz n) { if (n) __builtin_memmove(d, s, (uz)n); }
static void xset(void *d, int c, iz n)  { if (n) __builtin_memset(d, c, (uz)n); }
static i32  imin(i32 a, i32 b) { return a<b ? a : b; }
static i32  imax(i32 a, i32 b) { return a>b ? a : b; }
static i32  clamp(i32 v, i32 lo, i32 hi) { return v<lo ? lo : v>hi ? hi : v; }
static iz   izmin(iz a, iz b) { return a<b ? a : b; }


